const env = $('Envelope In').first().json;
const scope = env.payload.usage_scope || 'organic_social';
const now = Date.now();
const failures = [];

for (const a of ($json.assets || [])) {
  const r = a.rights || {};
  if (!r.license || r.license === 'unknown') { failures.push({ asset_id: a.asset_id, reason: 'license_unknown' }); continue; }
  if (r.expires_at && Date.parse(r.expires_at) < now) { failures.push({ asset_id: a.asset_id, reason: 'license_expired', expired_at: r.expires_at }); continue; }
  if (Array.isArray(r.usage_scope) && r.usage_scope.length && !r.usage_scope.includes(scope)) { failures.push({ asset_id: a.asset_id, reason: 'scope_not_covered', needed: scope, covered: r.usage_scope }); continue; }
  if (a.depicts_person && !r.talent_release) { failures.push({ asset_id: a.asset_id, reason: 'talent_release_missing' }); }
}

return [{ json: {
  status: failures.length ? 'fail' : 'pass',
  failures,
  checked: ($json.assets || []).length,
  may_proceed: failures.length === 0
} }];
